srcDoc.css:
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.nt-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: #1E293B;
  border: 1px solid #334155;
  border-radius: 6px;
  font-family: system-ui;
}
table.nt { border-collapse: collapse; width: max-content; min-width: 100%; background: #1E293B; }
table.nt th { padding: 10px 14px; font-size: 12px; font-weight: 700; color: #F1F5F9; white-space: nowrap; text-align: left; border-bottom: 2px solid #475569; background: #334155; position: sticky; top: 0; }
table.nt td { padding: 8px 14px; font-size: 12px; color: #E2E8F0; border-bottom: 1px solid #334155; vertical-align: top; }
table.nt td.nowrap { white-space: nowrap; }
table.nt td.chat { white-space: pre-line; min-width: 320px; max-width: 520px; }
table.nt a { color: #93c5fd; text-decoration: underline; }
.empty { padding: 20px; color: #94A3B8; text-align: center; font-family: system-ui; }

srcDoc.js:
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
var COLS = [
  { key: 'location',   label: 'Locations',          cls: 'nowrap' },
  { key: 'billId',     label: 'Bill ID',            cls: 'nowrap' },
  { key: 'workflow',   label: 'Workflow State',     cls: 'nowrap' },
  { key: 'markedDate', label: 'Marked for Payment', cls: 'nowrap' },
  { key: 'chatDate',   label: 'Last Chat Date',     cls: 'nowrap' },
  { key: 'chatUser',   label: 'Last Chat User',     cls: 'nowrap' },
  { key: 'chatTags',   label: 'Last Chat Tags',     cls: 'nowrap' },
  { key: 'chatHistory',label: 'Chat History',       cls: 'chat' }
];
function render(model) {
  var root = document.getElementById('root');
  if (!root) return;
  var rows = (model && model.rows) || [];
  if (!rows.length) {
    root.innerHTML = '<div class="empty">No data available</div>';
    return;
  }
  var h = '<table class="nt"><thead><tr>';
  COLS.forEach(function(c){ h += '<th>' + c.label + '</th>'; });
  h += '</tr></thead><tbody>';
  rows.forEach(function(r){
    h += '<tr>';
    COLS.forEach(function(c){
      h += '<td class="' + c.cls + '">' + esc(r[c.key]) + '</td>';
    });
    h += '</tr>';
  });
  h += '</tbody></table>';
  root.innerHTML = h;
}
appsmith.onReady(function(){
  render(appsmith.model);
  appsmith.onModelChange(function(m){ render(m); });
});

